Dispatch on the canonical discriminant — whether the pool is in-memory — rather than on the derived read_pool_size field:

```rust
pub fn read(&self) -> ReadConn<'_> {
    if self.path.is_none() {
        // In-memory: single shared connection, serialised
        let guard = self.write_conn.lock();
        return ReadConn::InMemory(WriteAsReadGuard { guard });
    }
    // File-backed: pop from bounded pool, block if exhausted
    let mut conns = self.read_conns.lock();
    while conns.is_empty() {
        self.read_available.wait(&mut conns);
    }
    let conn = conns.pop().expect("condvar woke but pool empty");
    ReadConn::Pooled(ReadGuard { conn: Some(conn), pool: self })
}
```
