impl ScopeTree {
    fn build(iter: impl IntoIterator<Item = ScopeNode>) -> Self {
        let iter = iter.into_iter();
        let (low, _) = iter.size_hint();
        let mut nodes = HashMap::with_capacity(low);
        let mut children: HashMap<i64, Vec<i64>> = HashMap::new();
        for node in iter {
            if let Some(pid) = node.parent_id {
                children.entry(pid).or_default().push(node.id);
            }
            nodes.insert(node.id, node);
        }
        Self { nodes, children }
    }

    pub fn load(conn: &Connection) -> Result<Self> {
        Ok(Self::build(ScopeStore::new(conn).list_all()?))
    }

    pub(crate) fn from_snapshot(snap: &crate::engine::snapshot::ScopeTreeSnapshot) -> Self {
        Self::build(snap.nodes.iter().cloned())
    }
}

fn build_hnsw_inner(entries: impl IntoIterator<Item = (i64, Vec<f32>)>) -> Result<HnswInner> {
    use rand::SeedableRng;
    let mut index = Hnsw::new_params_and_prng(
        CosineMetric,
        hnsw::Params::new().ef_construction(200),
        SmallRng::seed_from_u64(HNSW_SEED),
    );
    let mut searcher: Searcher<u32> = Searcher::default();
    let mut index_to_fact = Vec::new();
    let mut fact_to_hnsw = HashMap::new();
    for (fact_id, embedding) in entries {
        let hnsw_id = index.insert(embedding, &mut searcher);
        if hnsw_id != index_to_fact.len() {
            return Err(MemoryError::Internal(format!(...)));
        }
        index_to_fact.push(fact_id);
        fact_to_hnsw.insert(fact_id, hnsw_id);
    }
    Ok(HnswInner { index, index_to_fact, fact_to_hnsw, tombstones: HashSet::new() })
}

