Defensive guards (cheap, belt-and-suspenders):

    // ancestors(): cap the walk at node_count to make a cycle terminate
    pub fn ancestors(&self, scope_id: i64) -> Vec<i64> {
        let mut result = Vec::new();
        let mut current = Some(scope_id);
        let cap = self.nodes.len() + 1;
        while let Some(id) = current {
            if result.len() >= cap { break; }   // cycle guard
            result.push(id);
            current = self.nodes.get(&id).and_then(|n| n.parent_id);
        }
        result
    }

    // subtree(): visited set so a cycle in `children` terminates
    pub fn subtree(&self, scope_id: i64) -> Vec<i64> {
        let mut result = Vec::new();
        let mut seen = std::collections::HashSet::new();
        let mut queue = std::collections::VecDeque::new();
        queue.push_back(scope_id);
        while let Some(id) = queue.pop_front() {
            if !seen.insert(id) { continue; }   // already visited -> cycle
            result.push(id);
            if let Some(child_ids) = self.children.get(&id) {
                for &cid in child_ids { queue.push_back(cid); }
            }
        }
        result
    }

