fn snapshot_roundtrip_preserves_topology_and_edge_data() {
    let mut g = MemoryGraph::new();
    g.add_edge(10, 20, EdgeData { edge_id: 1, relation_type: "contradicts".into(), weight: 0.75 });
    g.add_edge(20, 30, EdgeData { edge_id: 2, relation_type: "supplements".into(), weight: 0.5 });

    let snap = g.to_snapshot();
    let g2 = MemoryGraph::from_snapshot(&snap);

    assert_eq!(g2.node_count(), g.node_count());
    assert_eq!(g2.edge_count(), g.edge_count());
    assert_eq!(g2.neighbors(10), vec![20]);
    assert_eq!(g2.neighbors(20), vec![30]);
    // Verify edge_data is preserved (weight, relation_type accessible via edge listing)
    let snap2 = g2.to_snapshot();
    assert_eq!(snap2.edges[0].weight, 0.75);
    assert_eq!(snap2.edges[0].relation_type, "contradicts");
}
