#[test]
fn pool_read_blocks_and_unblocks_when_returned() {
    use std::sync::Arc;
    use std::thread;

    let dir = tempfile::tempdir().unwrap();
    let db_path = dir.path().join("test.db");
    // Pool with exactly 1 read connection
    let pool = Arc::new(ConnectionPool::open(&db_path, 4, 1, None).unwrap());

    let pool2 = Arc::clone(&pool);
    let r1 = pool.read(); // exhausts the pool

    let handle = thread::spawn(move || {
        // This will block until r1 is dropped
        let _r2 = pool2.read();
    });

    drop(r1); // triggers notify_one
    handle.join().unwrap(); // second read must succeed
}
```

