#[test]
fn inherited_on_mid_node_includes_ancestors_and_all_descendants() {
    let tree = setup_tree();
    let user_id = tree.resolve_path("user:michael").unwrap();
    let demo_id = tree.resolve_path("user:michael/project:demo").unwrap();
    let other_id = tree.resolve_path("user:michael/project:other").unwrap();
    let inh = tree.inherited(user_id);
    // ancestors: user_id, root (2) + subtree descendants: demo_id, other_id (2) = 4
    assert_eq!(inh.len(), 4);
    assert!(inh.contains(&user_id));
    assert!(inh.contains(&tree.root_id()));
    assert!(inh.contains(&demo_id));
    assert!(inh.contains(&other_id));
    // scope_id appears exactly once (dedup invariant)
    assert_eq!(inh.iter().filter(|&&id| id == user_id).count(), 1);
}
```

