fn score_fact(fact: &Fact, query: &MemoryQuery) -> Option<f64> {
    if let Some(ref ft) = query.fact_type {
        if &fact.fact_type != ft {
            return None;
        }
    }
    let mut score = 0.0_f64;
    let mut matched = query.text.is_none() && query.embedding.is_none();
    if !matched { score = 1.0; }
    if let Some(ref text) = query.text {
        if fact.content.to_lowercase().contains(&text.to_lowercase()) {
            score += 1.0;
            matched = true;
        }
    }
    if let Some(ref emb) = query.embedding {
        if emb.len() == fact.embedding.len() && !fact.embedding.is_empty() {
            let cos = f64::from(cosine_similarity(emb, &fact.embedding));
            if cos > 0.0 { score += cos; matched = true; }
        }
    }
    matched.then_some(score)
}

