```rust
#[cfg(test)]
mod proptest_graph {
    use super::*;
    use proptest::prelude::*;

    proptest! {
        #![proptest_config(proptest::test_runner::Config::with_cases(64))]

        #[test]
        fn degree_equals_in_plus_out(
            edges in proptest::collection::vec((0i64..20, 0i64..20, 0i64..100), 0..20usize)
        ) {
            let mut g = MemoryGraph::new();
            for (i, (src, tgt, eid)) in edges.iter().enumerate() {
                g.add_edge(*src, *tgt, EdgeData { edge_id: *eid + i as i64, relation_type: "r".into(), weight: 1.0 });
            }
            for id in g.node_map.keys().copied().collect::<Vec<_>>() {
                // degree must equal sum of directed neighbor counts
                let out = g.graph.neighbors_directed(g.node_map[&id], petgraph::Direction::Outgoing).count();
                let inp = g.graph.neighbors_directed(g.node_map[&id], petgraph::Direction::Incoming).count();
                prop_assert_eq!(g.degree(id), out + inp);
            }
        }

        #[test]
        fn snapshot_roundtrip_preserves_degree(
            edges in proptest::collection::vec((0i64..20, 0i64..20), 0..15usize)
        ) {
            let mut g = MemoryGraph::new();
            for (i, (src, tgt)) in edges.iter().enumerate() {
                g.add_edge(*src, *tgt, EdgeData { edge_id: i as i64, relation_type: "x".into(), weight: 0.5 });
            }
            let g2 = MemoryGraph::from_snapshot(&g.to_snapshot());
            prop_assert_eq!(g.edge_count(), g2.edge_count());
        }
    }
}
